package com.learnagent.workspace;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="workspace_projects")public class WorkspaceProject{@Id private UUID id;@Column(name="course_id")private UUID courseId;@Column(nullable=false)private String name;@Column(nullable=false,unique=true)private String slug;@Enumerated(EnumType.STRING)@Column(nullable=false)private WorkspaceTemplate template;@Enumerated(EnumType.STRING)@Column(nullable=false)private WorkspaceStatus status;@Column(name="root_path",nullable=false,unique=true)private String rootPath;@Column(columnDefinition="text")private String description;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected WorkspaceProject(){}public WorkspaceProject(UUID courseId,String name,String slug,WorkspaceTemplate template,String rootPath,String description){id=UUID.randomUUID();this.courseId=courseId;this.name=name;this.slug=slug;this.template=template;this.rootPath=rootPath;this.description=description;status=WorkspaceStatus.CREATED;}@PrePersist void create(){createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();}public void status(WorkspaceStatus value){status=value;}public UUID getId(){return id;}public UUID getCourseId(){return courseId;}public String getName(){return name;}public String getSlug(){return slug;}public WorkspaceTemplate getTemplate(){return template;}public WorkspaceStatus getStatus(){return status;}public String getRootPath(){return rootPath;}public String getDescription(){return description;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
